SELECT id, name, jsonb_array_length(walls::jsonb) as total_segs, (SELECT count(*) FROM jsonb_array_elements(walls::jsonb) w WHERE w->>'kind' = 'window') as windows, (SELECT count(*) FROM jsonb_array_elements(walls::jsonb) w WHERE w->>'kind' = 'door') as doors, (SELECT count(*) FROM jsonb_array_elements(walls::jsonb) w WHERE w->>'kind' = 'wall') as walls_only FROM tactical_scenes WHERE id = '557378d7-557c-45b7-bf3c-42c2f73840a0';
